  if (res.statusCode === 200) {
    console.log('Audit log successful');
  } else {
    console.error(`Audit failed with status: ${res.statusCode}`);
  }
});

req.on('error', (e) => {
  console.error('Audit request failed:', e.message);
  // Continue execution even if audit fails (compliance logging is non-blocking)
});

req.write(payload);
req.end();

