const fs = require('fs');
const path = require('path');

// Directory containing migration SQL files
class DatabaseMigrator {
  constructor(migrationsDir = './migrations') {
    this.migrationsDir = path.resolve(migrationsDir);
  }

  // Read all SQL files from the migrations directory in sorted order
  getMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationsDir);
      // Filter only .sql files and sort them alphabetically
      return files
        .filter(file => path.extname(file).toLowerCase() === '.sql')
        .sort()
        .map(file => path.join(this.migrationsDir, file));
    } catch (err) {
      if (err.code === 'ENOENT') {
        console.error(`Migrations directory not found: ${this.migrationsDir}`);
      } else {
        console.error(`Error reading migrations directory: ${err.message}`);
      }
      return [];
    }
  }

  // Simulate applying migrations by logging filenames
  run() {
    console.log('Starting database migration...');
    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found or directory missing.');
      return;
    }

    migrationFiles.forEach(file => {
      console.log(`Applying migration: ${path.basename(file)}`);
      // Here you would normally execute the SQL file
      // Example: executeSQL(fs.readFileSync(file, 'utf8'));
    });

    console.log('Migration completed.');
  }
}

// Run migration if script is executed directly
if (require.main === module) {
  const migrator = new DatabaseMigrator();
  migrator.run();
}

module.exports = DatabaseMigrator;

