const fs = require('fs');
const path = require('path');

// Simple dotenv implementation for loading environment variables
function loadEnv(envFile) {
  try {
    const contents = fs.readFileSync(envFile, 'utf8');
    const lines = contents.split('\n');

    lines.forEach(line => {
      // Skip empty lines and comments
      if (line.trim() === '' || line.trim().startsWith('#')) {
        return;
      }

      // Parse key-value pairs
      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('=');

      if (key && value) {
        // Remove quotes from value if present
        const cleanedValue = value.trim().replace(/^"|"$/g, '').replace(/^\'|'$/g, '');
        process.env[key.trim()] = cleanedValue;
      }
    });
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.log(`${envFile} not found, skipping...`);
    } else {
      console.error(`Error reading ${envFile}:`, error.message);
    }
  }
}

// Load environment variables from .env.test
loadEnv('.env.test');

// Directory where migration files are stored
